if ( ! function_exists( 'platinum_svg' ) ) {
	/**
	 * Outputs the SVG code for a requested icon.
	 */
	function platinum_svg( $icon_name ) {
		echo platinum_get_svg( $icon_name ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
	}
}

if ( ! function_exists( 'platinum_nav_chevron' ) ) {
	/**
	 * Nav dropdown chevron markup.
	 */
	function platinum_nav_chevron() {
		return '<svg class="chevron-down" width="8" height="5" viewBox="0 0 8 5" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M1 1L4 4L7 1" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
	}
}
